\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Field Report: Moraine Deposits of the East Valley Transect}
\author{K.~Alvarez and P.~Osei}
\date{October 2025}

\begin{document}
\maketitle

\section{Setting}
The east valley transect crosses three  distinct moraine belts, each
mapped on foot during the September campaign. The outermost belt,
shown in figure 1, is a broad ridge of unsorted till standing about
twelve metres above the valley floor.

\section{Moraine Belts}
The middle belt is narrower and steeper, and its crest, marked in
figure 2, carries large granite erratics up to three metres across.
Between the middle and inner belts lies a  wide outwash plain crossed
by meltwater channels that were still active during the survey.

\begin{figure}[h]
\centering
\fbox{\rule{0pt}{2cm}\rule{5cm}{0pt}}
\caption{The outermost moraine belt seen from the south}
\label{fig:ridge}
\end{figure}

\begin{figure}[h]
\centering
\fbox{\rule{0pt}{2cm}\rule{5cm}{0pt}}
\caption{Granite erratics on the crest of the middle belt}
\label{fig:erratics}
\end{figure}

\section{Dating}
Organic material beneath the inner belt gives a maximum age for its
deposition, and the relative sequence of the three belts is clear
from their cross-cutting relations. The innermost deposit, drawn in
figure 3, is a small delta built into a former ice-dammed lake.

\begin{figure}[h]
\centering
\fbox{\rule{0pt}{2cm}\rule{5cm}{0pt}}
\caption{The inner delta deposit at the valley head}
\label{fig:delta}
\end{figure}

\section{Conclusions}
	The three belts record at least two readvances of the east valley
glacier, and the  relative ages are consistent with the regional
chronology. Further dating of the outwash plain is planned for the
next field season.
\end{document}

